    "Read this computer instruction:\n\nAlways shut down the computer properly after use. Do not turn off the power switch directly.\n\nWhat should you do after using the computer?": "यह कंप्यूटर निर्देश पढ़ें:\n\nउपयोग के बाद हमेशा कंप्यूटर को ठीक से बंद कर दें। बिजली का स्विच सीधे बंद न करें।\n\nकंप्यूटर का उपयोग करने के बाद आपको क्या करना चाहिए?",
