    "Read this short story:\n\nBobby has a little puppy named Bruno. Bruno likes to chew on soft toys. Yesterday, Bruno chewed Bobby's red ball.\n\nWhat is the name of Bobby's puppy?": "ಈ ಸಣ್ಣ ಕಥೆಯನ್ನು ಓದಿ:\n\nಬಾಬಿಗೆ ಬ್ರೂನೋ ಎಂಬ ಪುಟ್ಟ ನಾಯಿಮರಿ ಇದೆ. ಬ್ರೂನೋ ಮೃದುವಾದ ಆಟಿಕೆಗಳನ್ನು ಅಗಿಯಲು ಇಷ್ಟಪಡುತ್ತಾನೆ. ನಿನ್ನೆ, ಬ್ರೂನೋ ಬಾಬಿಯ ಕೆಂಪು ಚೆಂಡನ್ನು ಅಗಿಯುತ್ತಾನೆ.\n\nಬಾಬಿಯ ನಾಯಿಮರಿಯ ಹೆಸರೇನು?",
