    "Read the story above again. What object did the puppy chew?": "ಮೇಲಿನ ಕಥೆಯನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ನಾಯಿಮರಿ ಯಾವ ವಸ್ತುವನ್ನು ಅಗಿಯಿತು?",
    "Read this classroom schedule:\n\nDrawing class starts at 10 AM. Story hour starts at 11 AM. Playground play starts at 12 PM.\n\nAt what time does Story hour start?": "ಈ ತರಗತಿಯ ವೇಳಾಪಟ್ಟಿಯನ್ನು ಓದಿ:\n\nಚಿತ್ರಕಲೆ ತರಗತಿಯು ಬೆಳಿಗ್ಗೆ 10 ಗಂಟೆಗೆ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ. ಕಥೆಯ ಸಮಯ 11 AM ಕ್ಕೆ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ. ಆಟದ ಮೈದಾನದ ಆಟವು ಮಧ್ಯಾಹ್ನ 12 ಗಂಟೆಗೆ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ.\n\nಸ್ಟೋರಿ ಅವರ್ ಯಾವ ಸಮಯದಲ್ಲಿ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ?",
    "Soft doll": "ಮೃದುವಾದ ಗೊಂಬೆ",
    "Read this warning box:\n\nChildren must wash their hands before lunch. Do not play with soil after washing.\n\nWhen should children wash their hands?": "ಈ ಎಚ್ಚರಿಕೆ ಪೆಟ್ಟಿಗೆಯನ್ನು ಓದಿ:\n\nಮಕ್ಕಳು ಊಟದ ಮೊದಲು ಕೈ ತೊಳೆಯಬೇಕು. ತೊಳೆದ ನಂತರ ಮಣ್ಣಿನೊಂದಿಗೆ ಆಟವಾಡಬೇಡಿ.\n\nಮಕ್ಕಳು ಯಾವಾಗ ಕೈ ತೊಳೆಯಬೇಕು?",
