    "Read this diary entry:\n\nMonday: Planted a sunflower seed. Wednesday: Sprout came out. Friday: Two small leaves appeared.\n\nOn which day did the sprout come out?": "ಈ ಡೈರಿ ನಮೂದನ್ನು ಓದಿ:\n\nಸೋಮವಾರ: ಸೂರ್ಯಕಾಂತಿ ಬೀಜವನ್ನು ನೆಡಲಾಗಿದೆ. ಬುಧವಾರ: ಮೊಳಕೆ ಹೊರಬಂದಿತು. ಶುಕ್ರವಾರ: ಎರಡು ಸಣ್ಣ ಎಲೆಗಳು ಕಾಣಿಸಿಕೊಂಡವು.\n\nಚಿಗುರು ಯಾವ ದಿನ ಬಂತು?",
    "Read the diary entry again. What plant seed was planted?": "ಡೈರಿ ಬರಹವನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ಯಾವ ಸಸ್ಯ ಬೀಜವನ್ನು ನೆಡಲಾಯಿತು?",
    "Read this announcement:\n\nToday is very rainy. All students must stay inside the classroom during recess.\n\nWhy must students stay inside?": "ಈ ಪ್ರಕಟಣೆಯನ್ನು ಓದಿ:\n\nಇಂದು ತುಂಬಾ ಮಳೆಯಾಗಿದೆ. ಎಲ್ಲಾ ವಿದ್ಯಾರ್ಥಿಗಳು ಬಿಡುವಿನ ವೇಳೆಯಲ್ಲಿ ತರಗತಿಯ ಒಳಗೆ ಇರಬೇಕು.\n\nವಿದ್ಯಾರ್ಥಿಗಳು ಒಳಗೆ ಏಕೆ ಇರಬೇಕು?",
