    "Level 1 Assessment (TEEN)": "ಹಂತ 1 ಮೌಲ್ಯಮಾಪನ (TEEN)",
    "Test checking capability at Level 1 for teen learners.": "ಹದಿಹರೆಯದ ಕಲಿಯುವವರಿಗೆ ಹಂತ 1 ರಲ್ಲಿ ಪರೀಕ್ಷಿಸುವ ಸಾಮರ್ಥ್ಯವನ್ನು ಪರೀಕ್ಷಿಸಿ.",
    "Read this classroom poster:\n\nOur class has 12 boys and 14 girls. We have a pet turtle named Shelly.\n\nWhat pet does the class have?": "ಈ ತರಗತಿಯ ಪೋಸ್ಟರ್ ಓದಿ:\n\nನಮ್ಮ ತರಗತಿಯಲ್ಲಿ 12 ಹುಡುಗರು ಮತ್ತು 14 ಹುಡುಗಿಯರಿದ್ದಾರೆ. ನಮ್ಮಲ್ಲಿ ಶೆಲ್ಲಿ ಎಂಬ ಮುದ್ದಿನ ಆಮೆ ಇದೆ.\n\nವರ್ಗವು ಯಾವ ಸಾಕುಪ್ರಾಣಿಗಳನ್ನು ಹೊಂದಿದೆ?",
    "Read this library instruction:\n\nPut books back on the shelf after reading. Do not leave books on the table.\n\nWhere should you put books after reading?": "ಈ ಗ್ರಂಥಾಲಯದ ಸೂಚನೆಯನ್ನು ಓದಿ:\n\nಓದಿದ ನಂತರ ಪುಸ್ತಕಗಳನ್ನು ಮತ್ತೆ ಕಪಾಟಿನಲ್ಲಿ ಇರಿಸಿ. ಮೇಜಿನ ಮೇಲೆ ಪುಸ್ತಕಗಳನ್ನು ಬಿಡಬೇಡಿ.\n\nಓದಿದ ನಂತರ ಪುಸ್ತಕಗಳನ್ನು ಎಲ್ಲಿ ಹಾಕಬೇಕು?",
    "Read the classroom poster again. How many boys are in the class?": "ತರಗತಿಯ ಪೋಸ್ಟರ್ ಅನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ತರಗತಿಯಲ್ಲಿ ಎಷ್ಟು ಹುಡುಗರಿದ್ದಾರೆ?",
    "Which letter is different?": "ಯಾವ ಅಕ್ಷರವು ವಿಭಿನ್ನವಾಗಿದೆ?",
    "Which letter matches the shape of capital 'B'?": "ಯಾವ ಅಕ್ಷರವು ಕ್ಯಾಪಿಟಲ್ 'B' ಆಕಾರಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ?",
    "Which word rhymes with 'Ball'?": "ಯಾವ ಪದವು 'Ball' ನೊಂದಿಗೆ ಪ್ರಾಸಬದ್ಧವಾಗಿದೆ?",
    "Which letter has a circular curve?": "ಯಾವ ಅಕ್ಷರವು ವೃತ್ತಾಕಾರದ ವಕ್ರರೇಖೆಯನ್ನು ಹೊಂದಿದೆ?",
