    "Read the library warning again. What is the fine per day for late returns?": "ಲೈಬ್ರರಿ ಎಚ್ಚರಿಕೆಯನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ತಡವಾಗಿ ಹಿಂತಿರುಗಿಸಿದರೆ ದಿನಕ್ಕೆ ದಂಡ ಎಷ್ಟು?",
    "Read the announcement again. When will the sports day move to Monday?": "ಪ್ರಕಟಣೆಯನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ಕ್ರೀಡಾ ದಿನವು ಸೋಮವಾರಕ್ಕೆ ಯಾವಾಗ ಚಲಿಸುತ್ತದೆ?",
    "Level 5 Assessment (TEEN)": "ಹಂತ 5 ಮೌಲ್ಯಮಾಪನ (TEEN)",
    "Test checking capability at Level 5 for teen learners.": "ಹದಿಹರೆಯದ ಕಲಿಯುವವರಿಗೆ 5 ನೇ ಹಂತದಲ್ಲಿ ಪರೀಕ್ಷಾ ಸಾಮರ್ಥ್ಯವನ್ನು ಪರೀಕ್ಷಿಸಿ.",
    "Read this library warning:\n\nLibrary books must be returned within 7 days. A fine of 5 rupees per day is charged for late returns.\n\nHow many days can you keep a book without a fine?": "ಈ ಗ್ರಂಥಾಲಯದ ಎಚ್ಚರಿಕೆಯನ್ನು ಓದಿ:\n\nಲೈಬ್ರರಿ ಪುಸ್ತಕಗಳನ್ನು 7 ದಿನಗಳಲ್ಲಿ ಹಿಂತಿರುಗಿಸಬೇಕು. ತಡವಾಗಿ ಹಿಂತಿರುಗಿಸಿದರೆ ದಿನಕ್ಕೆ 5 ರೂಪಾಯಿ ದಂಡ ವಿಧಿಸಲಾಗುತ್ತದೆ.\n\nದಂಡವಿಲ್ಲದೆ ನೀವು ಎಷ್ಟು ದಿನ ಪುಸ್ತಕವನ್ನು ಇಡಬಹುದು?",
    "Read this school announcement:\n\nThe school sports day is scheduled for Friday. In case of heavy rain, it will be moved to Monday.\n\nOn which day is the sports day scheduled first?": "ಈ ಶಾಲೆಯ ಪ್ರಕಟಣೆಯನ್ನು ಓದಿ:\n\nಶಾಲೆಯ ಕ್ರೀಡಾ ದಿನವನ್ನು ಶುಕ್ರವಾರ ನಿಗದಿಪಡಿಸಲಾಗಿದೆ. ಭಾರೀ ಮಳೆಯಾದರೆ ಸೋಮವಾರಕ್ಕೆ ಸ್ಥಳಾಂತರಿಸಲಾಗುವುದು.\n\nಯಾವ ದಿನದಂದು ಕ್ರೀಡಾ ದಿನವನ್ನು ಮೊದಲು ನಿಗದಿಪಡಿಸಲಾಗಿದೆ?",
