    "Read this computer instruction:\n\nAlways shut down the computer properly after use. Do not turn off the power switch directly.\n\nWhat should you do after using the computer?": "ಈ ಕಂಪ್ಯೂಟರ್ ಸೂಚನೆಯನ್ನು ಓದಿ:\n\nಬಳಕೆಯ ನಂತರ ಯಾವಾಗಲೂ ಕಂಪ್ಯೂಟರ್ ಅನ್ನು ಸರಿಯಾಗಿ ಸ್ಥಗಿತಗೊಳಿಸಿ. ವಿದ್ಯುತ್ ಸ್ವಿಚ್ ಅನ್ನು ನೇರವಾಗಿ ಆಫ್ ಮಾಡಬೇಡಿ.\n\nಕಂಪ್ಯೂಟರ್ ಬಳಸಿದ ನಂತರ ನೀವು ಏನು ಮಾಡಬೇಕು?",
    "Shut down properly": "ಸರಿಯಾಗಿ ಸ್ಥಗಿತಗೊಳಿಸಿ",
    "Read this student identity card:\n\nName: Rahul Sharma. Age: 16. School: Model High School. Roll No: 24.\n\nHow old is Rahul Sharma?": "ಈ ವಿದ್ಯಾರ್ಥಿ ಗುರುತಿನ ಚೀಟಿಯನ್ನು ಓದಿ:\n\nಹೆಸರು : ರಾಹುಲ್ ಶರ್ಮಾ. ವಯಸ್ಸು: 16. ಶಾಲೆ: ಮಾಡೆಲ್ ಹೈಸ್ಕೂಲ್. ರೋಲ್ ಸಂಖ್ಯೆ: 24.\n\nರಾಹುಲ್ ಶರ್ಮಾ ಅವರ ವಯಸ್ಸು ಎಷ್ಟು?",
    "If students want": "ವಿದ್ಯಾರ್ಥಿಗಳು ಬಯಸಿದರೆ",
    "Read this timetable entry:\n\nMath Class: Room 101. Physics Lab: Room 204. Chemistry Lab: Room 305. All classes start on time.\n\nWhere is the Physics Lab located?": "ಈ ವೇಳಾಪಟ್ಟಿ ನಮೂದನ್ನು ಓದಿ:\n\nಗಣಿತ ತರಗತಿ: ಕೊಠಡಿ 101. ಭೌತಶಾಸ್ತ್ರ ಪ್ರಯೋಗಾಲಯ: ಕೊಠಡಿ 204. ರಸಾಯನಶಾಸ್ತ್ರ ಪ್ರಯೋಗಾಲಯ: ಕೊಠಡಿ 305. ಎಲ್ಲಾ ತರಗತಿಗಳು ಸಮಯಕ್ಕೆ ಪ್ರಾರಂಭವಾಗುತ್ತವೆ.\n\nಭೌತಶಾಸ್ತ್ರ ಪ್ರಯೋಗಾಲಯ ಎಲ್ಲಿದೆ?",
    "Ruler": "ಆಡಳಿತಗಾರ",
    "Senior team": "ಹಿರಿಯ ತಂಡ",
    "Calculator": "ಕ್ಯಾಲ್ಕುಲೇಟರ್",
    "Junior team": "ಜೂನಿಯರ್ ತಂಡ",
    "All students": "ಎಲ್ಲಾ ವಿದ್ಯಾರ್ಥಿಗಳು",
    "Visitors": "ಸಂದರ್ಶಕರು",
    "Blue pen": "ನೀಲಿ ಪೆನ್",
    "Read this exam notice:\n\nBring a blue pen and a ruler for the exam. Calculators are strictly prohibited.\n\nWhat object can you NOT bring to the exam?": "ಈ ಪರೀಕ್ಷೆಯ ಸೂಚನೆಯನ್ನು ಓದಿ:\n\nಪರೀಕ್ಷೆಗೆ ನೀಲಿ ಪೆನ್ನು ಮತ್ತು ರೂಲರ್ ತನ್ನಿ. ಕ್ಯಾಲ್ಕುಲೇಟರ್‌ಗಳನ್ನು ಕಟ್ಟುನಿಟ್ಟಾಗಿ ನಿಷೇಧಿಸಲಾಗಿದೆ.\n\nನೀವು ಯಾವ ವಸ್ತುವನ್ನು ಪರೀಕ್ಷೆಗೆ ತರಲು ಸಾಧ್ಯವಿಲ್ಲ?",
    "Read the student identity card again. What is the roll number of Rahul?": "ವಿದ್ಯಾರ್ಥಿ ಗುರುತಿನ ಚೀಟಿಯನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ರಾಹುಲ್ ರೋಲ್ ನಂಬರ್ ಎಷ್ಟು?",
    "Read this playground schedule:\n\nThe football field is reserved for the senior team from 4 PM to 6 PM daily.\n\nWho is the football field reserved for between 4 PM and 6 PM?": "ಈ ಆಟದ ಮೈದಾನದ ವೇಳಾಪಟ್ಟಿಯನ್ನು ಓದಿ:\n\nಫುಟ್ಬಾಲ್ ಮೈದಾನವನ್ನು ಪ್ರತಿದಿನ ಸಂಜೆ 4 ರಿಂದ ಸಂಜೆ 6 ರವರೆಗೆ ಹಿರಿಯ ತಂಡಕ್ಕೆ ಕಾಯ್ದಿರಿಸಲಾಗಿದೆ.\n\n4 PM ಮತ್ತು 6 PM ರ ನಡುವೆ ಫುಟ್ಬಾಲ್ ಮೈದಾನವನ್ನು ಯಾರಿಗಾಗಿ ಕಾಯ್ದಿರಿಸಲಾಗಿದೆ?",
    "Identify the capital letter 'H'.": "ದೊಡ್ಡ ಅಕ್ಷರ 'H' ಅನ್ನು ಗುರುತಿಸಿ.",
    "Which shape is different from the others?": "ಯಾವ ಆಕಾರವು ಇತರರಿಗಿಂತ ಭಿನ್ನವಾಗಿದೆ?",
    "Level 1 Assessment (ADULT)": "ಹಂತ 1 ಮೌಲ್ಯಮಾಪನ (ವಯಸ್ಕ)",
    "Find the lowercase letter shape for 'p'.": "'p' ಗಾಗಿ ಸಣ್ಣ ಅಕ್ಷರದ ಆಕಾರವನ್ನು ಹುಡುಕಿ.",
    "Find the lowercase letter 't'.": "ಸಣ್ಣ ಅಕ್ಷರ 't' ಅನ್ನು ಹುಡುಕಿ.",
    "Which letter looks like a cross shape?": "ಯಾವ ಅಕ್ಷರವು ಅಡ್ಡ ಆಕಾರದಂತೆ ಕಾಣುತ್ತದೆ?",
    "Which letter starting sound matches the word 'Market'?": "ಯಾವ ಅಕ್ಷರದ ಆರಂಭದ ಧ್ವನಿಯು 'Market' ಪದಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ?",
    "Which letter matches the shape of uppercase 'D'?": "ದೊಡ್ಡಕ್ಷರ 'D' ಯ ಆಕಾರಕ್ಕೆ ಯಾವ ಅಕ್ಷರ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ?",
    "Find the lowercase shape matching 'n'.": "ಲೋವರ್ಕೇಸ್ ಆಕಾರದ ಹೊಂದಾಣಿಕೆ 'n' ಅನ್ನು ಹುಡುಕಿ.",
