    "Marked as present": "ಪ್ರಸ್ತುತ ಎಂದು ಗುರುತಿಸಲಾಗಿದೆ",
    "Read the office instruction again. What happens if an employee arrives late without approval?": "ಕಚೇರಿ ಸೂಚನೆಯನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ಉದ್ಯೋಗಿ ಅನುಮೋದನೆಯಿಲ್ಲದೆ ತಡವಾಗಿ ಬಂದರೆ ಏನಾಗುತ್ತದೆ?",
    "Stop driving": "ಚಾಲನೆ ನಿಲ್ಲಿಸಿ",
    "Read this office instruction:\n\nAll employees must log their attendance before 9:30 AM. Late arrivals will be marked as half-day leave unless approved.\n\nWhat is the latest time to log attendance without being marked late?": "ಈ ಕಚೇರಿ ಸೂಚನೆಯನ್ನು ಓದಿ:\n\nಎಲ್ಲಾ ಉದ್ಯೋಗಿಗಳು 9:30 AM ಮೊದಲು ತಮ್ಮ ಹಾಜರಾತಿಯನ್ನು ಲಾಗ್ ಮಾಡಬೇಕು. ಅನುಮೋದಿಸದ ಹೊರತು ತಡವಾಗಿ ಬಂದವರನ್ನು ಅರ್ಧ ದಿನದ ರಜೆ ಎಂದು ಗುರುತಿಸಲಾಗುತ್ತದೆ.\n\nತಡವಾಗಿ ಗುರುತಿಸದೆ ಹಾಜರಾತಿಯನ್ನು ಲಾಗ್ ಮಾಡಲು ಇತ್ತೀಚಿನ ಸಮಯ ಯಾವುದು?",
    "30 days": "30 ದಿನಗಳು",
    "Bank passbook": "ಬ್ಯಾಂಕ್ ಪಾಸ್ಬುಕ್",
    "15th of this month": "ಈ ತಿಂಗಳ 15",
    "14 days": "14 ದಿನಗಳು",
