    "20th of this month": "ಈ ತಿಂಗಳ 20",
    "Identity card": "ಗುರುತಿನ ಚೀಟಿ",
    "Read the store refund policy again. What document must you present to get a refund?": "ಅಂಗಡಿ ಮರುಪಾವತಿ ನೀತಿಯನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ಮರುಪಾವತಿ ಪಡೆಯಲು ನೀವು ಯಾವ ಡಾಕ್ಯುಮೆಂಟ್ ಅನ್ನು ಪ್ರಸ್ತುತಪಡಿಸಬೇಕು?",
    "Original bill": "ಮೂಲ ಬಿಲ್",
    "Read this electricity board warning:\n\nPlease pay the electricity bill before the 20th of this month to avoid power disconnection.\n\nBefore which date should you pay the bill?": "ಈ ವಿದ್ಯುತ್ ಮಂಡಳಿಯ ಎಚ್ಚರಿಕೆಯನ್ನು ಓದಿ:\n\nವಿದ್ಯುತ್ ಸಂಪರ್ಕ ಕಡಿತಗೊಳಿಸುವುದನ್ನು ತಪ್ಪಿಸಲು ದಯವಿಟ್ಟು ಈ ತಿಂಗಳ 20 ರೊಳಗೆ ವಿದ್ಯುತ್ ಬಿಲ್ ಪಾವತಿಸಿ.\n\nಯಾವ ದಿನಾಂಕದ ಮೊದಲು ನೀವು ಬಿಲ್ ಅನ್ನು ಪಾವತಿಸಬೇಕು?",
    "Read this store refund policy:\n\nRefunds are only given within 14 days of purchase. The original bill must be presented for all refunds.\n\nWithin how many days can you request a refund?": "ಈ ಅಂಗಡಿ ಮರುಪಾವತಿ ನೀತಿಯನ್ನು ಓದಿ:\n\nಮರುಪಾವತಿಯನ್ನು ಖರೀದಿಸಿದ 14 ದಿನಗಳಲ್ಲಿ ಮಾತ್ರ ನೀಡಲಾಗುತ್ತದೆ. ಎಲ್ಲಾ ಮರುಪಾವತಿಗಳಿಗೆ ಮೂಲ ಬಿಲ್ ಅನ್ನು ಪ್ರಸ್ತುತಪಡಿಸಬೇಕು.\n\nಎಷ್ಟು ದಿನಗಳಲ್ಲಿ ನೀವು ಮರುಪಾವತಿಗೆ ವಿನಂತಿಸಬಹುದು?",
    "10th of this month": "ಈ ತಿಂಗಳ 10 ನೇ ತಾರೀಖು",
    "Marked as half-day leave": "ಅರ್ಧ ದಿನ ರಜೆ ಎಂದು ಗುರುತಿಸಲಾಗಿದೆ",
    "30th of this month": "ಈ ತಿಂಗಳ 30",
    "Read this doctor notice:\n\nTake two spoons of cough syrup three times a day. Shake the bottle well before use.\n\nHow many times a day should you take the medicine?": "ವೈದ್ಯರ ಸೂಚನೆಯನ್ನು ಓದಿ:\n\nದಿನಕ್ಕೆ ಮೂರು ಬಾರಿ ಎರಡು ಚಮಚ ಕೆಮ್ಮು ಸಿರಪ್ ತೆಗೆದುಕೊಳ್ಳಿ. ಬಳಕೆಗೆ ಮೊದಲು ಬಾಟಲಿಯನ್ನು ಚೆನ್ನಾಗಿ ಅಲ್ಲಾಡಿಸಿ.\n\nನೀವು ದಿನಕ್ಕೆ ಎಷ್ಟು ಬಾರಿ ಔಷಧಿ ತೆಗೆದುಕೊಳ್ಳಬೇಕು?",
