    "Read this railway announcement:\n\nThe train to Mumbai is delayed by two hours due to fog. It will now arrive at 11:00 AM.\n\nWhy is the train delayed?": "ಈ ರೈಲ್ವೆ ಪ್ರಕಟಣೆಯನ್ನು ಓದಿ:\n\nಮಂಜಿನಿಂದಾಗಿ ಮುಂಬೈಗೆ ತೆರಳುವ ರೈಲು ಎರಡು ಗಂಟೆ ತಡವಾಗಿದೆ. ಇದು ಈಗ 11:00 AM ಕ್ಕೆ ಆಗಮಿಸುತ್ತದೆ.\n\nರೈಲು ಏಕೆ ತಡವಾಗಿದೆ?",
