    "Read this banking notice:\n\nNever share your 4-digit PIN with anyone. The bank staff will never ask for your PIN.\n\nWhat should you never share?": "ಈ ಬ್ಯಾಂಕಿಂಗ್ ಸೂಚನೆಯನ್ನು ಓದಿ:\n\nನಿಮ್ಮ 4-ಅಂಕಿಯ ಪಿನ್ ಅನ್ನು ಯಾರೊಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳಬೇಡಿ. ಬ್ಯಾಂಕ್ ಸಿಬ್ಬಂದಿ ನಿಮ್ಮ ಪಿನ್ ಅನ್ನು ಎಂದಿಗೂ ಕೇಳುವುದಿಲ್ಲ.\n\nನೀವು ಎಂದಿಗೂ ಏನನ್ನು ಹಂಚಿಕೊಳ್ಳಬಾರದು?",
