    "Test checking capability at Level 5 for senior learners.": "ಹಿರಿಯ ಕಲಿಯುವವರಿಗೆ 5 ನೇ ಹಂತದಲ್ಲಿ ಪರೀಕ್ಷಾ ಸಾಮರ್ಥ್ಯವನ್ನು ಪರೀಕ್ಷಿಸಿ.",
    "Read the medical label again. When should you take the capsules?": "ವೈದ್ಯಕೀಯ ಲೇಬಲ್ ಅನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ಕ್ಯಾಪ್ಸುಲ್ಗಳನ್ನು ಯಾವಾಗ ತೆಗೆದುಕೊಳ್ಳಬೇಕು?",
    "Read this family letter:\n\nDear Grandpa, I will visit you on Saturday evening at 4 PM. Please keep the gate unlocked.\n\nOn which day is the grandchild visiting?": "ಈ ಕುಟುಂಬ ಪತ್ರವನ್ನು ಓದಿ:\n\nಆತ್ಮೀಯ ಅಜ್ಜ, ನಾನು ಶನಿವಾರ ಸಂಜೆ 4 ಗಂಟೆಗೆ ನಿಮ್ಮನ್ನು ಭೇಟಿ ಮಾಡುತ್ತೇನೆ. ದಯವಿಟ್ಟು ಗೇಟ್ ಅನ್ನು ಅನ್ಲಾಕ್ ಮಾಡಿ.\n\nಮೊಮ್ಮಗ ಯಾವ ದಿನ ಭೇಟಿ ನೀಡುತ್ತಾನೆ?",
    "Read the letter again. What time is the visitor arriving?": "ಪತ್ರವನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ಸಂದರ್ಶಕರು ಯಾವ ಸಮಯಕ್ಕೆ ಆಗಮಿಸುತ್ತಿದ್ದಾರೆ?",
    "Read this medical label:\n\nTake 1 capsule twice daily, once in the morning and once at night after food.\n\nHow many capsules should you take in one day?": "ಈ ವೈದ್ಯಕೀಯ ಲೇಬಲ್ ಅನ್ನು ಓದಿ:\n\n1 ಕ್ಯಾಪ್ಸುಲ್ ಅನ್ನು ದಿನಕ್ಕೆ ಎರಡು ಬಾರಿ ತೆಗೆದುಕೊಳ್ಳಿ, ಒಮ್ಮೆ ಬೆಳಿಗ್ಗೆ ಮತ್ತು ಒಮ್ಮೆ ರಾತ್ರಿ ಊಟದ ನಂತರ.\n\nಒಂದು ದಿನದಲ್ಲಿ ನೀವು ಎಷ್ಟು ಕ್ಯಾಪ್ಸುಲ್ಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಬೇಕು?",
