    "Read the doctor recipe again. How many drops should you use?": "ವೈದ್ಯರ ಪಾಕವಿಧಾನವನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ನೀವು ಎಷ್ಟು ಹನಿಗಳನ್ನು ಬಳಸಬೇಕು?",
    "Read the park notice again. When does the track close in the morning?": "ಉದ್ಯಾನವನದ ಸೂಚನೆಯನ್ನು ಮತ್ತೊಮ್ಮೆ ಓದಿ. ಬೆಳಿಗ್ಗೆ ಟ್ರ್ಯಾಕ್ ಯಾವಾಗ ಮುಚ್ಚುತ್ತದೆ?",
    "Read this park notice:\n\nThe senior citizen walking track is open from 6:00 AM to 9:00 AM daily. Please do not run on this track.\n\nWhat is the track used for?": "ಈ ಪಾರ್ಕ್ ಸೂಚನೆಯನ್ನು ಓದಿ:\n\nಹಿರಿಯ ನಾಗರಿಕರ ವಾಕಿಂಗ್ ಟ್ರ್ಯಾಕ್ ಪ್ರತಿದಿನ ಬೆಳಗ್ಗೆ 6:00 ರಿಂದ 9:00 ರವರೆಗೆ ತೆರೆದಿರುತ್ತದೆ. ದಯವಿಟ್ಟು ಈ ಟ್ರ್ಯಾಕ್‌ನಲ್ಲಿ ಓಡಬೇಡಿ.\n\nಟ್ರ್ಯಾಕ್ ಅನ್ನು ಯಾವುದಕ್ಕಾಗಿ ಬಳಸಲಾಗುತ್ತದೆ?",
    "Read this doctor recipe:\n\nUse three drops of eye drops in left eye. Do it before going to sleep.\n\nWhere should you use the eye drops?": "ಈ ವೈದ್ಯರ ಪಾಕವಿಧಾನವನ್ನು ಓದಿ:\n\nಎಡಗಣ್ಣಿನಲ್ಲಿ ಮೂರು ಹನಿ ಕಣ್ಣಿನ ಹನಿಗಳನ್ನು ಬಳಸಿ. ಮಲಗುವ ಮುನ್ನ ಇದನ್ನು ಮಾಡಿ.\n\nಕಣ್ಣಿನ ಹನಿಗಳನ್ನು ಎಲ್ಲಿ ಬಳಸಬೇಕು?",
