    "Level 2 Assessment (CHILD)": "స్థాయి 2 అసెస్‌మెంట్ (పిల్లలు)",
    "Test checking capability at Level 2 for child learners.": "చైల్డ్ లెర్నర్స్ కోసం లెవెల్ 2లో టెస్ట్ చెకింగ్ సామర్ధ్యం.",
