    "Which letter is different from the others?": "ఏ అక్షరం మిగతా వాటి కంటే భిన్నంగా ఉంటుంది?",
    "Find the lowercase letter that matches 'b'.": "'b'కి సరిపోలే చిన్న అక్షరాన్ని కనుగొనండి.",
