    "Which word rhyms with 'Sun'?": "'Sun'తో ఏ పదం ప్రాసనిస్తుంది?",
    "Test checking capability at Level 3 for child learners.": "చైల్డ్ లెర్నర్స్ కోసం లెవల్ 3 వద్ద పరీక్ష తనిఖీ సామర్థ్యం.",
    "Which letter matches the ending sound of the word 'Ball'?": "'Ball' అనే పదం ముగింపు ధ్వనికి ఏ అక్షరం సరిపోతుంది?",
