    "Read the library warning again. What is the fine per day for late returns?": "లైబ్రరీ హెచ్చరికను మళ్లీ చదవండి. ఆలస్యమైన రిటర్న్స్ కోసం రోజుకు జరిమానా ఎంత?",
    "Read this school announcement:\n\nThe school sports day is scheduled for Friday. In case of heavy rain, it will be moved to Monday.\n\nOn which day is the sports day scheduled first?": "ఈ పాఠశాల ప్రకటనను చదవండి:\n\nపాఠశాల క్రీడా దినోత్సవం శుక్రవారం జరగనుంది. భారీ వర్షం కురిస్తే సోమవారానికి తరలిస్తారు.\n\nస్పోర్ట్స్ డేని ముందుగా ఏ రోజు షెడ్యూల్ చేస్తారు?",
    "Level 5 Assessment (TEEN)": "స్థాయి 5 అసెస్‌మెంట్ (టీన్)",
    "Read this library warning:\n\nLibrary books must be returned within 7 days. A fine of 5 rupees per day is charged for late returns.\n\nHow many days can you keep a book without a fine?": "ఈ లైబ్రరీ హెచ్చరికను చదవండి:\n\nలైబ్రరీ పుస్తకాలను 7 రోజులలోపు తిరిగి ఇవ్వాలి. ఆలస్యమైన రిటర్న్స్ కోసం రోజుకు 5 రూపాయల జరిమానా విధించబడుతుంది.\n\nజరిమానా లేకుండా పుస్తకాన్ని ఎన్ని రోజులు ఉంచుకోవచ్చు?",
    "Test checking capability at Level 5 for teen learners.": "యుక్తవయస్సు నేర్చుకునేవారి కోసం స్థాయి 5 వద్ద పరీక్ష తనిఖీ సామర్థ్యాన్ని పరీక్షించండి.",
    "Read the announcement again. When will the sports day move to Monday?": "ప్రకటనను మళ్లీ చదవండి. క్రీడా దినోత్సవం సోమవారానికి ఎప్పుడు మారుతుంది?",
