    "Read this timetable entry:\n\nMath Class: Room 101. Physics Lab: Room 204. Chemistry Lab: Room 305. All classes start on time.\n\nWhere is the Physics Lab located?": "ఈ టైమ్‌టేబుల్ ఎంట్రీని చదవండి:\n\nగణిత తరగతి: గది 101. ఫిజిక్స్ ల్యాబ్: గది 204. కెమిస్ట్రీ ల్యాబ్: గది 305. అన్ని తరగతులు సమయానికి ప్రారంభమవుతాయి.\n\nఫిజిక్స్ ల్యాబ్ ఎక్కడ ఉంది?",
    "Read this student identity card:\n\nName: Rahul Sharma. Age: 16. School: Model High School. Roll No: 24.\n\nHow old is Rahul Sharma?": "ఈ విద్యార్థి గుర్తింపు కార్డును చదవండి:\n\nపేరు: రాహుల్ శర్మ. వయస్సు: 16. పాఠశాల: మోడల్ హై స్కూల్. రోల్ సంఖ్య: 24.\n\nరాహుల్ శర్మ వయస్సు ఎంత?",
    "Shut down properly": "సరిగ్గా షట్ డౌన్ చేయండి",
    "If teachers are busy": "ఉపాధ్యాయులు బిజీగా ఉంటే",
    "Read this computer instruction:\n\nAlways shut down the computer properly after use. Do not turn off the power switch directly.\n\nWhat should you do after using the computer?": "ఈ కంప్యూటర్ సూచనలను చదవండి:\n\nఉపయోగించిన తర్వాత ఎల్లప్పుడూ కంప్యూటర్‌ను సరిగ్గా షట్ డౌన్ చేయండి. పవర్ స్విచ్‌ను నేరుగా ఆఫ్ చేయవద్దు.\n\nకంప్యూటర్ ఉపయోగించిన తర్వాత మీరు ఏమి చేయాలి?",
