    "Read this exam notice:\n\nBring a blue pen and a ruler for the exam. Calculators are strictly prohibited.\n\nWhat object can you NOT bring to the exam?": "ఈ పరీక్ష ప్రకటన చదవండి:\n\nపరీక్ష కోసం నీలిరంగు పెన్ను మరియు రూలర్ తీసుకురండి. కాలిక్యులేటర్లు ఖచ్చితంగా నిషేధించబడ్డాయి.\n\nమీరు ఏ వస్తువును పరీక్షకు తీసుకురాలేరు?",
    "Read this playground schedule:\n\nThe football field is reserved for the senior team from 4 PM to 6 PM daily.\n\nWho is the football field reserved for between 4 PM and 6 PM?": "ఈ ప్లేగ్రౌండ్ షెడ్యూల్ చదవండి:\n\nఫుట్‌బాల్ మైదానం ప్రతిరోజూ సాయంత్రం 4 నుండి సాయంత్రం 6 గంటల వరకు సీనియర్ జట్టు కోసం రిజర్వ్ చేయబడింది.\n\n4 PM మరియు 6 PM మధ్య ఫుట్‌బాల్ మైదానం ఎవరి కోసం రిజర్వ్ చేయబడింది?",
    "Read the student identity card again. What is the roll number of Rahul?": "విద్యార్థి గుర్తింపు కార్డును మళ్లీ చదవండి. రాహుల్ రోల్ నంబర్ ఎంత?",
    "Which letter matches the shape of uppercase 'D'?": "పెద్ద అక్షరం 'D' ఆకారానికి ఏ అక్షరం సరిపోతుంది?",
    "Complete the sequence: O, P, Q, __": "క్రమాన్ని పూర్తి చేయండి: O, P, Q, __",
    "Identify the letter 'L'.": "'L' అక్షరాన్ని గుర్తించండి.",
    "Find the lowercase letter 't'.": "చిన్న అక్షరం 't'ని కనుగొనండి.",
    "Level 1 Assessment (ADULT)": "స్థాయి 1 అసెస్‌మెంట్ (వయోజనులు)",
    "Identify the capital letter 'H'.": "పెద్ద అక్షరం 'H'ని గుర్తించండి.",
    "Find the lowercase letter shape for 'p'.": "'p' కోసం చిన్న అక్షరం ఆకారాన్ని కనుగొనండి.",
    "Level 2 Assessment (ADULT)": "స్థాయి 2 అసెస్‌మెంట్ (వయోజనులు)",
    "Which shape is different from the others?": "ఏ ఆకారం ఇతరుల నుండి భిన్నంగా ఉంటుంది?",
    "Which letter looks like a cross shape?": "ఏ అక్షరం క్రాస్ ఆకారంలో కనిపిస్తుంది?",
    "Find the lowercase shape matching 'n'.": "'n'కి సరిపోలే చిన్న అక్షరం ఆకారాన్ని కనుగొనండి.",
    "Find the capital letter 'G'.": "పెద్ద అక్షరం 'G'ని కనుగొనండి.",
    "Which letter starting sound matches the word 'Market'?": "ఏ అక్షరం ప్రారంభ ధ్వని 'Market' అనే పదానికి సరిపోతుంది?",
    "Test checking capability at Level 1 for adult learners.": "వయోజన అభ్యాసకులకు లెవల్ 1 వద్ద పరీక్ష తనిఖీ సామర్థ్యం.",
    "Test checking capability at Level 2 for adult learners.": "వయోజన అభ్యాసకుల కోసం స్థాయి 2 వద్ద పరీక్ష తనిఖీ సామర్థ్యాన్ని పరీక్షించండి.",
