    "What sound does the letter 'W' make in 'Water'?": "'W' అక్షరం 'Water'లో ఏ శబ్దం చేస్తుంది?",
    "Which word starts with the 'O' sound?": "'O' శబ్దంతో ఏ పదం ప్రారంభమవుతుంది?",
    "Identify the missing vowel: 'B_nk'.": "తప్పిపోయిన అచ్చును గుర్తించండి: 'B_nk'.",
