    "Marked as half-day leave": "హాఫ్ డే లీవ్‌గా గుర్తించారు",
    "Read this doctor notice:\n\nTake two spoons of cough syrup three times a day. Shake the bottle well before use.\n\nHow many times a day should you take the medicine?": "ఈ డాక్టర్ నోటీసు చదవండి:\n\nరోజుకు మూడు సార్లు రెండు చెంచాల దగ్గు సిరప్ తీసుకోండి. ఉపయోగం ముందు బాటిల్‌ను బాగా కదిలించండి.\n\nమీరు రోజుకు ఎన్నిసార్లు ఔషధం తీసుకోవాలి?",
    "Read this store refund policy:\n\nRefunds are only given within 14 days of purchase. The original bill must be presented for all refunds.\n\nWithin how many days can you request a refund?": "ఈ స్టోర్ రీఫండ్ విధానాన్ని చదవండి:\n\nకొనుగోలు చేసిన 14 రోజులలోపు మాత్రమే వాపసు ఇవ్వబడుతుంది. అన్ని వాపసుల కోసం అసలు బిల్లు తప్పనిసరిగా సమర్పించాలి.\n\nమీరు ఎన్ని రోజులలోపు వాపసు కోసం అభ్యర్థించవచ్చు?",
