    "Read the sign: 'EXIT'. Where does it lead?": "அடையாளத்தைப் படியுங்கள்: 'EXIT'. அது எங்கு செல்கிறது?",
    "Way out": "வெளியேறும் வழி",
    "Read the sign: 'DANGER'. What does it tell you?": "'DANGER' என்ற அடையாளத்தைப் படியுங்கள். அது உங்களுக்கு என்ன சொல்கிறது?",
