    "Shout and sing": "கத்தவும் பாடவும்",
    "Read the library sign: 'SILENCE'. What does it mean?": "நூலக அடையாளத்தைப் படியுங்கள்: 'SILENCE'. அது என்ன அர்த்தம்?",
