    "Anyone freely": "எவரும் சுதந்திரமாக",
    "Nobody without permission": "அனுமதி இல்லாமல் யாரும் இல்லை",
    "Read the school gate sign: 'NO ENTRY'. Who can go in?": "பள்ளி வாசல் பலகையைப் படியுங்கள்: 'NO ENTRY'. யார் உள்ளே போகலாம்?",
    "Level 5 Assessment (CHILD)": "நிலை 5 மதிப்பீடு (குழந்தை)",
    "Only cars": "கார்கள் மட்டுமே",
    "Read this short story:\n\nBobby has a little puppy named Bruno. Bruno likes to chew on soft toys. Yesterday, Bruno chewed Bobby's red ball.\n\nWhat is the name of Bobby's puppy?": "இந்த சிறுகதையைப் படியுங்கள்:\n\nபாபிக்கு புருனோ என்ற குட்டி நாய்க்குட்டி உள்ளது. புருனோ மென்மையான பொம்மைகளை மெல்ல விரும்புகிறார். நேற்று, புருனோ பாபியின் சிவப்பு பந்தை மென்று தின்றார்.\n\nபாபியின் நாய்க்குட்டியின் பெயர் என்ன?",
    "Test checking capability at Level 5 for child learners.": "குழந்தை கற்பவர்களுக்கு நிலை 5 இல் சோதனைச் சோதனை திறன்.",
    "Rex": "ரெக்ஸ்",
