    "11 AM": "காலை 11 மணி",
    "Spoon": "கரண்டி",
    "Shoes": "காலணிகள்",
    "Before lunch": "மதிய உணவுக்கு முன்",
    "12 PM": "12 PM",
    "Before sleeping": "தூங்கும் முன்",
    "After lunch": "மதிய உணவுக்குப் பிறகு",
    "9 AM": "காலை 9 மணி",
    "Read the story above again. What object did the puppy chew?": "மேலே உள்ள கதையை மீண்டும் படியுங்கள். நாய்க்குட்டி என்ன பொருளை மெல்லியது?",
    "Read this warning box:\n\nChildren must wash their hands before lunch. Do not play with soil after washing.\n\nWhen should children wash their hands?": "இந்த எச்சரிக்கை பெட்டியைப் படியுங்கள்:\n\nகுழந்தைகள் மதிய உணவுக்கு முன் கைகளை கழுவ வேண்டும். கழுவிய பின் மண்ணுடன் விளையாட வேண்டாம்.\n\nகுழந்தைகள் எப்போது கைகளை கழுவ வேண்டும்?",
    "Soft doll": "மென்மையான பொம்மை",
    "Only at night": "இரவில் மட்டும்",
    "Read this classroom schedule:\n\nDrawing class starts at 10 AM. Story hour starts at 11 AM. Playground play starts at 12 PM.\n\nAt what time does Story hour start?": "இந்த வகுப்பறை அட்டவணையைப் படியுங்கள்:\n\nவரைதல் வகுப்பு காலை 10 மணிக்கு தொடங்குகிறது. கதை நேரம் காலை 11 மணிக்கு தொடங்குகிறது. விளையாட்டு மைதானம் மதியம் 12 மணிக்கு தொடங்குகிறது.\n\nகதை நேரம் எந்த நேரத்தில் தொடங்குகிறது?",
    "10 AM": "காலை 10 மணி",
