    "To study math": "கணிதம் படிக்க",
    "Tulip": "துலிப்",
    "Read the diary entry again. What plant seed was planted?": "டைரி பதிவை மீண்டும் படிக்கவும். எந்த தாவர விதை நடப்பட்டது?",
    "Because the school is closed": "ஏனென்றால் பள்ளி மூடப்பட்டுள்ளது",
    "Read this diary entry:\n\nMonday: Planted a sunflower seed. Wednesday: Sprout came out. Friday: Two small leaves appeared.\n\nOn which day did the sprout come out?": "இந்த டைரி பதிவை படிக்கவும்:\n\nதிங்கள்: ஒரு சூரியகாந்தி விதை நடப்பட்டது. புதன்: முளை வந்தது. வெள்ளி: இரண்டு சிறிய இலைகள் தோன்றின.\n\nஎந்த நாளில் முளை வந்தது?",
    "Because it is rainy": "ஏனென்றால் மழைக்காலம்",
    "Monday": "திங்கட்கிழமை",
    "Because it is hot": "ஏனென்றால் அது சூடாக இருக்கிறது",
    "Read this announcement:\n\nToday is very rainy. All students must stay inside the classroom during recess.\n\nWhy must students stay inside?": "இந்த அறிவிப்பைப் படிக்கவும்:\n\nஇன்று மிகவும் மழை. அனைத்து மாணவர்களும் இடைவேளையின் போது வகுப்பறைக்குள் இருக்க வேண்டும்.\n\nமாணவர்கள் ஏன் உள்ளே இருக்க வேண்டும்?",
    "On the floor": "தரையில்",
    "On the shelf": "அலமாரியில்",
    "On the table": "மேஜையில்",
    "Sunflower": "சூரியகாந்தி",
    "Turtle": "ஆமை",
    "On the chair": "நாற்காலியில்",
    "Read this library instruction:\n\nPut books back on the shelf after reading. Do not leave books on the table.\n\nWhere should you put books after reading?": "இந்த நூலக வழிமுறைகளைப் படிக்கவும்:\n\nபடித்த பிறகு புத்தகங்களை மீண்டும் அலமாரியில் வைக்கவும். புத்தகங்களை மேசையில் வைக்க வேண்டாம்.\n\nபடித்த பிறகு புத்தகங்களை எங்கு வைக்க வேண்டும்?",
    "Read the classroom poster again. How many boys are in the class?": "வகுப்பறை சுவரொட்டியை மீண்டும் படியுங்கள். வகுப்பில் எத்தனை பையன்கள்?",
    "Level 1 Assessment (TEEN)": "நிலை 1 மதிப்பீடு (TEEN)",
    "Test checking capability at Level 1 for teen learners.": "டீன் ஏஜ் கற்கும் மாணவர்களுக்கான லெவல் 1ல் சோதனைச் சோதனை திறன்.",
    "Read this classroom poster:\n\nOur class has 12 boys and 14 girls. We have a pet turtle named Shelly.\n\nWhat pet does the class have?": "இந்த வகுப்பறை சுவரொட்டியைப் படியுங்கள்:\n\nஎங்கள் வகுப்பில் 12 ஆண்களும் 14 பெண்களும் உள்ளனர். எங்களிடம் ஷெல்லி என்று ஒரு செல்ல ஆமை உள்ளது.\n\nவகுப்பில் என்ன செல்லம் உள்ளது?",
    "Which letter matches the shape of capital 'B'?": "எந்த எழுத்து மூலதனம் 'B' வடிவத்துடன் பொருந்துகிறது?",
    "Which letter has a circular curve?": "எந்த எழுத்து வட்ட வளைவைக் கொண்டுள்ளது?",
    "Which word rhymes with 'Ball'?": "எந்த வார்த்தை 'Ball' உடன் ரைம் செய்கிறது?",
    "Level 2 Assessment (TEEN)": "நிலை 2 மதிப்பீடு (TEEN)",
    "Find the capital letter 'Z'.": "பெரிய எழுத்தான 'Z' ஐக் கண்டறியவும்.",
    "Find the capital letter 'E'.": "பெரிய எழுத்தான 'E' ஐக் கண்டறியவும்.",
    "Find the matching capital letter for 'd'.": "'d' க்கு பொருத்தமான பெரிய எழுத்தைக் கண்டறியவும்.",
    "Complete the sequence: K, L, M, __": "வரிசையை முடிக்கவும்: K, L, M, __",
    "Identify the lowercase shape for the letter 'g'.": "'g' என்ற எழுத்தின் சிற்றெழுத்து வடிவத்தைக் கண்டறியவும்.",
    "Which letter is different?": "எந்த எழுத்து வித்தியாசமானது?",
    "Identify the letter 'R'.": "'R' என்ற எழுத்தை அடையாளம் காணவும்.",
    "Identify lowercase shape matching 'h'.": "'h' உடன் பொருந்தும் சிற்றெழுத்து வடிவத்தைக் கண்டறியவும்.",
    "Test checking capability at Level 2 for teen learners.": "டீன் ஏஜ் கற்பவர்களுக்கு நிலை 2 இல் சோதனைச் சோதனை திறன்.",
    "Identify the missing letter in 'Pl_y'.": "'Pl_y' இல் விடுபட்ட எழுத்தை அடையாளம் காணவும்.",
    "Which letter starts the sound of the word 'Game'?": "'Game' என்ற வார்த்தையின் ஒலியைத் தொடங்கும் எழுத்து எது?",
    "Bull": "காளை",
    "Bat": "வௌவால்",
    "Great": "பெரிய",
    "Grip": "பிடி",
