    "Identify the missing vowel: 'Fr_nd'.": "விடுபட்ட உயிரெழுத்தை அடையாளம் காணவும்: 'Fr_nd'.",
    "Identify the missing letter: 'L_brary'.": "விடுபட்ட எழுத்தை அடையாளம் காணவும்: 'L_brary'.",
