    "Choose the correct spelling of the device we use to call people:": "நபர்களை அழைக்க நாங்கள் பயன்படுத்தும் சாதனத்தின் சரியான எழுத்துப்பிழையைத் தேர்வு செய்யவும்:",
    "Test checking capability at Level 4 for teen learners.": "டீன் ஏஜ் கற்பவர்களுக்கு நிலை 4 இல் சோதனைச் சோதனை திறன்.",
    "Find the spelling of the fifth month of the year:": "ஆண்டின் ஐந்தாவது மாதத்தின் எழுத்துப்பிழையைக் கண்டறியவும்:",
