    "Complete: 'We play football in the ______.'": "முழுமையானது: 'We play football in the ______.'",
    "Read the sign: 'NO SMOKING'. What does it mean?": "'NO SMOKING' என்ற அடையாளத்தைப் படியுங்கள். அது என்ன அர்த்தம்?",
    "park": "பூங்கா",
    "Read the road sign: 'NO CYCLING'. What does it mean?": "சாலைப் பலகையைப் படியுங்கள்: 'NO CYCLING'. அது என்ன அர்த்தம்?",
    "Cycles are allowed": "சுழற்சிகள் அனுமதிக்கப்படுகின்றன",
