    "Do not throw garbage": "குப்பைகளை வீச வேண்டாம்",
    "Read the sign: 'NO TRASHING'. What should you do?": "'NO TRASHING' என்ற அடையாளத்தைப் படியுங்கள். நீங்கள் என்ன செய்ய வேண்டும்?",
    "Keep bags here": "பைகளை இங்கே வைத்திருங்கள்",
    "Complete: 'Can you show me the ______ to the lab?'": "முழுமையானது: 'Can you show me the ______ to the lab?'",
    "Complete: 'I need to study for my ______ tomorrow.'": "முழுமை: 'I need to study for my ______ tomorrow.'",
    "Do not light cigarettes": "சிகரெட் பற்றவைக்காதீர்கள்",
    "Throw trash here": "குப்பையை இங்கே எறியுங்கள்",
