    "Nobody at all": "யாரும் இல்லை",
    "Read the sign: 'AUTHORIZED PERSONNEL ONLY'. Who can enter?": "'AUTHORIZED PERSONNEL ONLY' என்ற அடையாளத்தைப் படியுங்கள். யார் நுழைய முடியும்?",
    "Only staff with permission": "அனுமதி பெற்ற ஊழியர்கள் மட்டுமே",
    "Read the sign: 'KEEP LEFT'. What should a driver do?": "'KEEP LEFT' என்ற அடையாளத்தைப் படியுங்கள். ஒரு டிரைவர் என்ன செய்ய வேண்டும்?",
