    "Salary is increased": "சம்பளம் உயர்த்தப்பட்டுள்ளது",
    "Read the office instruction again. What happens if an employee arrives late without approval?": "அலுவலக அறிவுறுத்தலை மீண்டும் படிக்கவும். ஒரு ஊழியர் ஒப்புதல் இல்லாமல் தாமதமாக வந்தால் என்ன நடக்கும்?",
    "Level 5 Assessment (ADULT)": "நிலை 5 மதிப்பீடு (வயது வந்தோர்)",
    "Test checking capability at Level 5 for adult learners.": "வயது வந்தோருக்கான 5 ஆம் நிலையில் சோதனைச் சோதனை திறன்.",
    "Read this office instruction:\n\nAll employees must log their attendance before 9:30 AM. Late arrivals will be marked as half-day leave unless approved.\n\nWhat is the latest time to log attendance without being marked late?": "இந்த அலுவலக அறிவுறுத்தலைப் படியுங்கள்:\n\nஅனைத்து ஊழியர்களும் தங்கள் வருகையை காலை 9:30 மணிக்கு முன் பதிவு செய்ய வேண்டும். அங்கீகரிக்கப்படாவிட்டால் தாமதமாக வருபவர்கள் அரை நாள் விடுப்பாகக் குறிக்கப்படும்.\n\nதாமதமாகக் குறிக்கப்படாமல் வருகையைப் பதிவு செய்வதற்கான சமீபத்திய நேரம் எது?",
