    "Read the store refund policy again. What document must you present to get a refund?": "ஸ்டோர் ரீஃபண்ட் கொள்கையை மீண்டும் படிக்கவும். பணத்தைத் திரும்பப் பெற என்ன ஆவணத்தை சமர்ப்பிக்க வேண்டும்?",
    "10th of this month": "இம்மாதம் 10ஆம் தேதி",
    "Read this store refund policy:\n\nRefunds are only given within 14 days of purchase. The original bill must be presented for all refunds.\n\nWithin how many days can you request a refund?": "இந்த ஸ்டோர் ரீஃபண்ட் கொள்கையைப் படிக்கவும்:\n\nவாங்கிய 14 நாட்களுக்குள் மட்டுமே பணத்தைத் திரும்பப் பெற முடியும். அனைத்து ரீஃபண்டுகளுக்கும் அசல் பில் சமர்ப்பிக்கப்பட வேண்டும்.\n\nஎத்தனை நாட்களுக்குள் பணத்தைத் திரும்பக் கோரலாம்?",
    "Read this doctor notice:\n\nTake two spoons of cough syrup three times a day. Shake the bottle well before use.\n\nHow many times a day should you take the medicine?": "இந்த மருத்துவ அறிவிப்பைப் படியுங்கள்:\n\nஇரண்டு ஸ்பூன் இருமல் சிரப்பை ஒரு நாளைக்கு மூன்று முறை எடுத்துக் கொள்ளுங்கள். பயன்படுத்துவதற்கு முன் பாட்டிலை நன்றாக அசைக்கவும்.\n\nஒரு நாளைக்கு எத்தனை முறை மருந்து எடுக்க வேண்டும்?",
    "Read this electricity board warning:\n\nPlease pay the electricity bill before the 20th of this month to avoid power disconnection.\n\nBefore which date should you pay the bill?": "மின்சார வாரியத்தின் இந்த எச்சரிக்கையைப் படியுங்கள்:\n\nமின் துண்டிப்பை தவிர்க்க இம்மாதம் 20ம் தேதிக்குள் மின் கட்டணத்தை செலுத்த வேண்டும்.\n\nஎந்த தேதிக்கு முன் நீங்கள் பில் செலுத்த வேண்டும்?",
    "30th of this month": "இம்மாதம் 30ஆம் தேதி",
    "Three times": "மூன்று முறை",
    "Four times": "நான்கு முறை",
    "Two times": "இரண்டு முறை",
    "Drink cold water": "குளிர்ந்த நீர் அருந்துங்கள்",
    "Your name": "உங்கள் பெயர்",
    "Bank address": "வங்கி முகவரி",
    "Once daily": "தினமும் ஒருமுறை",
    "Boil the syrup": "பாகில் கொதிக்கவும்",
    "Shake the bottle well": "பாட்டிலை நன்றாக அசைக்கவும்",
    "Mobile brand": "மொபைல் பிராண்ட்",
    "Read the doctor notice again. What should you do before taking the cough syrup?": "மருத்துவர் அறிவிப்பை மீண்டும் படியுங்கள். இருமல் சிரப் எடுப்பதற்கு முன் என்ன செய்ய வேண்டும்?",
    "Keep it in sun": "வெயிலில் வைக்கவும்",
    "4-digit PIN": "4 இலக்க பின்",
    "Read this banking notice:\n\nNever share your 4-digit PIN with anyone. The bank staff will never ask for your PIN.\n\nWhat should you never share?": "இந்த வங்கி அறிவிப்பைப் படிக்கவும்:\n\nஉங்கள் 4 இலக்க பின்னை யாருடனும் பகிர வேண்டாம். வங்கி ஊழியர்கள் உங்கள் பின்னைக் கேட்க மாட்டார்கள்.\n\nநீங்கள் எதைப் பகிரக்கூடாது?",
    "Read this railway announcement:\n\nThe train to Mumbai is delayed by two hours due to fog. It will now arrive at 11:00 AM.\n\nWhy is the train delayed?": "இந்த ரயில்வே அறிவிப்பை படிக்கவும்:\n\nபனிமூட்டம் காரணமாக மும்பை செல்லும் ரயில் இரண்டு மணி நேரம் தாமதமானது. இப்போது காலை 11:00 மணிக்கு வந்து சேரும்.\n\nரயில் ஏன் தாமதமாகிறது?",
    "10:30 AM": "காலை 10:30 மணி",
    "11:00 AM": "காலை 11:00 மணி",
    "Due to strike": "வேலை நிறுத்தம் காரணமாக",
    "12:00 PM": "12:00 PM",
    "Due to rain": "மழை காரணமாக",
    "Find the lowercase shape that matches 'h'.": "'h' உடன் பொருந்தும் சிற்றெழுத்து வடிவத்தைக் கண்டறியவும்.",
    "Identify the letter 'V'.": "'V' என்ற எழுத்தை அடையாளம் காணவும்.",
    "Level 1 Assessment (SENIOR)": "நிலை 1 மதிப்பீடு (SENIOR)",
    "Identify the capital letter 'T'.": "பெரிய எழுத்தான 'T' ஐ அடையாளம் காணவும்.",
    "Which letter matches the shape of capital 'C'?": "எந்த எழுத்து மூலதனம் 'C' வடிவத்துடன் பொருந்துகிறது?",
    "Read the railway announcement again. What is the new arrival time of the train?": "ரயில்வே அறிவிப்பை மீண்டும் படிக்கவும். ரயிலின் புதிய வருகை நேரம் என்ன?",
    "Due to engine issue": "என்ஜின் பிரச்சினை காரணமாக",
    "Which letter is different from others?": "எந்த எழுத்து மற்றவற்றிலிருந்து வேறுபட்டது?",
    "Due to fog": "மூடுபனி காரணமாக",
    "Test checking capability at Level 1 for senior learners.": "மூத்த கற்பவர்களுக்கு நிலை 1 இல் சோதனைச் சோதனை திறன்.",
