    "Lock": "பூட்டு",
    "Look": "பார்",
    "Which letter starts the sound of the word 'Home'?": "'Home' என்ற வார்த்தையின் ஒலியைத் தொடங்கும் எழுத்து எது?",
    "Complete the sequence: E, F, G, __": "வரிசையை முடிக்கவும்: E, F, G, __",
    "Identify the missing letter: 'T_me'.": "விடுபட்ட எழுத்தை அடையாளம் காணவும்: 'T_me'.",
    "Level 2 Assessment (SENIOR)": "நிலை 2 மதிப்பீடு (SENIOR)",
    "Which letter looks like a vertical post?": "எந்த எழுத்து செங்குத்து இடுகை போல் தெரிகிறது?",
    "Find the capital letter 'U'.": "பெரிய எழுத்தான 'U' ஐக் கண்டறியவும்.",
    "Find lowercase shape matching 'm'.": "'m' உடன் பொருந்தும் சிற்றெழுத்து வடிவத்தைக் கண்டறியவும்.",
    "Find the lowercase letter 'a'.": "'a' என்ற சிறிய எழுத்தைக் கண்டறியவும்.",
    "Which word rhymes with 'Clock'?": "எந்த வார்த்தை 'Clock' உடன் ஒலிக்கிறது?",
    "What sound does the letter 'M' make in 'Medicine'?": "மருத்துவத்தில் 'M' என்ற எழுத்து என்ன ஒலியை எழுப்புகிறது?",
    "Test checking capability at Level 2 for senior learners.": "மூத்த கற்பவர்களுக்கு நிலை 2 இல் சோதனைச் சோதனை திறன்.",
