    "What sound does double 'e' make in 'Seed'?": "'e'யில் இரட்டை 'Seed' என்ன ஒலி எழுப்புகிறது?",
    "Which word starts with the 'Sp' sound blend?": "எந்த வார்த்தை 'Sp' ஒலி கலவையுடன் தொடங்குகிறது?",
    "Identify the missing vowel: 'S_n'.": "விடுபட்ட உயிரெழுத்தை அடையாளம் காணவும்: 'S_n'.",
    "Which word rhymes with 'Day'?": "எந்த வார்த்தை 'Day' உடன் ரைம் செய்கிறது?",
    "Which word starts with the 'N' sound?": "எந்த வார்த்தை 'N' ஒலியில் தொடங்குகிறது?",
