    "Test checking capability at Level 3 for senior learners.": "மூத்த கற்பவர்களுக்கு நிலை 3 இல் சோதனைச் சோதனை திறன்.",
    "Choose the correct spelling of the substance used to cure illness:": "நோயைக் குணப்படுத்தப் பயன்படுத்தப்படும் பொருளின் சரியான எழுத்துப்பிழையைத் தேர்ந்தெடுக்கவும்:",
