    "What is the opposite word for 'Morning'?": "'Morning' என்பதற்கு எதிர் சொல் என்ன?",
    "Find the correct spelling of the liquid we drink to survive:": "உயிர்வாழ நாம் குடிக்கும் திரவத்தின் சரியான எழுத்துப்பிழையைக் கண்டறியவும்:",
