    "Read the hospital sign: 'SILENCE PLEASE'. What should you do?": "மருத்துவமனை அடையாளத்தைப் படியுங்கள்: 'SILENCE PLEASE'. நீங்கள் என்ன செய்ய வேண்டும்?",
